from taf.ue.rpc.mtk.mtk_rpc import MTKRPC
from taf.ue.plugin.mtk.mace.factory import MaceProxyFactory
from taf.internal.managedobject import ManagedObject


class MTKRPCProxy(ManagedObject):

    def __init__(self, config=None):
        super(MTKRPCProxy, self).__init__()

        self._config = config
        self._mtk_rpc = self.__init_rpc(self._config)

        self._mace_proxy_factory = MaceProxyFactory(config, self._mtk_rpc)
        self._mace_proxy = self._mace_proxy_factory.create()
        self._mace_proxy.add_prerequisite(self._mtk_rpc)
        self.add_prerequisite(self._mace_proxy)

    @staticmethod
    def __init_rpc(config):
        rpc = MTKRPC()
        rpc.configure(config['ue_pc_ip'], config['pyro_port'],
                      username=config['login'], password=config['password'],
                      server_dir=config['server_dir'], python_path=config['server_python'])
        return rpc

    def _setup(self):
        pass

    def get_ue_specific_methods_container(self):
        return self._mace_proxy

    @property
    def mace_proxy(self):
        return self._mace_proxy

    @property
    def mtk_rpc(self):
        return self._mtk_rpc

    def get_platform_info(self):
        return self._mace_proxy.get_platform_information()

    def _teardown(self):
        pass
